"""CPU-only probes of the supplied weights; no simulator imports or driving."""
import json
import numpy as np

NAMES = ('W1', 'b1', 'W2', 'b2', 'W3', 'b3')

def load(path='start.npz'):
    with np.load(path, allow_pickle=False) as z:
        return {k: z[k].copy() for k in NAMES}

def forward(d, x):
    h1 = np.tanh(x @ d['W1'] + d['b1'])
    h2 = np.tanh(h1 @ d['W2'] + d['b2'])
    z = h2 @ d['W3'] + d['b3']
    return np.tanh(z), h1, h2, z

def handmade():
    # Explicitly specified sensor scenarios, not samples generated by a simulator.
    straight = [.10, .116, .174, .324, .957, .957, .324, .174, .116, .10]
    left = [.10, .12, .17, .25, .34, .48, .62, .30, .13, .10]
    sharp_left = [.13, .15, .18, .22, .27, .34, .45, .50, .16, .09]
    toward_left = [.15, .20, .30, .50, .80, .30, .16, .09, .06, .05]
    shapes = [straight, left, left[::-1], sharp_left, sharp_left[::-1],
              toward_left, toward_left[::-1]]
    rows = []
    for rays in shapes:
        for scale in [.8, 1., 1.15]:
            for speed in [0., .35, .5, .65, .8, 1., 1.2]:
                for steer in [-.5, 0., .5]:
                    rows.append([*np.minimum(np.array(rays)*scale, 1.), speed, steer, 1.])
    return np.asarray(rows)

if __name__ == '__main__':
    np.set_printoptions(precision=4, suppress=True, linewidth=160)
    d = load()
    r = json.load(open('call01.json'))
    x = np.array([s['obs'] for tr in r['results']['strict_g1.0']['crash_traces'] for s in tr['steps']])
    a, h1, h2, z = forward(d, x)
    print('Crash trace logits ranges, means:', z.min(0), z.max(0), z.mean(0))
    print('Mean pedal contributions per h2 unit:', np.mean(h2*d['W3'][:,1], 0))
    print('Pedal local sensitivity per h2:', np.mean((1-h2*h2)*d['W3'][:,1], 0))
    print('Mean h1 activations:', h1.mean(0))
    print('Mean h2 activations:', h2.mean(0))
    base_x = handmade()
    a, h1, h2, z = forward(d, base_x)
    sensitivities = np.einsum('ij,nj->ni', d['W2'], (1-h2*h2)*d['W3'][:,0])
    # Removing the input-dependent part of a unit after absorbing its mean in b2.
    print('h1 steer influence, RMS linearized variation:', np.sqrt(np.mean(((h1-h1.mean(0))*sensitivities)**2, 0)))
    print('h1 mean on hand-made inputs:', h1.mean(0))
    print('Analytic output-logit input Jacobian on handmade input mean:')
    _, H1, H2, _ = forward(d, base_x.mean(0))
    J = (d['W1']*(1-H1**2)) @ (d['W2']*(1-H2**2)) @ d['W3']
    print(J)
    for sp in [0., .5, .7, .9, 1.1]:
        xx=base_x[0].copy(); xx[10:]=[sp, 0., 1.]
        print('straight speed',sp,'action/logits',forward(d,xx)[0],forward(d,xx)[3])
    for pp in [-1.,0.,1.]:
        xx=x[10].copy();xx[12]=pp
        print('corner prev_pedal',pp,'action/logits',forward(d,xx)[0],forward(d,xx)[3])
